package com.passion.knownow.core.rendering

data class TableModel(
    val header: List<String>,
    val rows: List<List<String>>,
    val kind: TableKind,
)

enum class TableKind { PROPERTIES, PARAMETERS, NAV_CARDS, GENERIC }

/**
 * ServiceNow pages carry two very different kinds of tabular content:
 *
 * - HTML `<table>` blocks generated by the DITA pipeline (field reference tables, nav cards)
 * - plain markdown pipe tables (`|Field|Description|`) written by hand in the source
 *
 * Both are lifted out of the markdown stream here and handed to [AdaptiveTable], because the
 * generic markdown table renderer splits every column evenly: on a phone a 50/50 split turns a
 * one-word field name into a wide empty gutter and squeezes the description into a thin ribbon.
 */
object HtmlTableParser {
    private val tableRegex = Regex("<table[^>]*>(.*?)</table>", RegexOption.DOT_MATCHES_ALL)
    private val rowRegex = Regex("<tr[^>]*>(.*?)</tr>", RegexOption.DOT_MATCHES_ALL)
    private val cellRegex = Regex("<t[hd][^>]*>(.*?)</t[hd]>", RegexOption.DOT_MATCHES_ALL)
    private val tagRegex = Regex("<[^>]+>")
    private val separatorCell = Regex("^:?-{2,}:?$")
    private val inlineLink = Regex("""\[([^\]]*)]\([^)]*\)""")
    private val emphasis = Regex("""(\*\*|__|\*|_|`)""")

    fun parse(html: String): TableModel {
        val tableMatch = tableRegex.find(html) ?: return TableModel(emptyList(), emptyList(), TableKind.GENERIC)
        val body = tableMatch.groupValues[1]
        val rows = rowRegex.findAll(body).map { r ->
            cellRegex.findAll(r.groupValues[1]).map { c ->
                plainInline(stripTags(c.groupValues[1]))
            }.toList()
        }.filter { it.isNotEmpty() }.toList()
        if (rows.isEmpty()) return TableModel(emptyList(), emptyList(), TableKind.GENERIC)
        val header = rows.firstOrNull()?.takeIf { body.contains("<th") } ?: emptyList()
        val dataRows = if (header.isNotEmpty()) rows.drop(1) else rows
        val colCount = (header.ifEmpty { dataRows.firstOrNull() } ?: emptyList()).size
        val kind = inferKind(header, colCount)
        return TableModel(header, dataRows, kind)
    }

    /** Splits a section into prose and table segments, in document order. */
    fun splitSegments(markdown: String): List<Segment> {
        val out = mutableListOf<Segment>()
        var last = 0
        for (m in tableRegex.findAll(markdown)) {
            out += splitTextSegments(markdown.substring(last, m.range.first))
            out += Segment.Table(parse(m.value))
            last = m.range.last + 1
        }
        out += splitTextSegments(markdown.substring(last))
        if (out.isEmpty()) out += Segment.Text(markdown)
        return mergeAdjacentTables(out)
    }

    private fun splitTextSegments(text: String): List<Segment> {
        val out = mutableListOf<Segment>()
        val prose = StringBuilder()
        val pipeBlock = mutableListOf<String>()

        fun flushProse() {
            val value = prose.toString().trim()
            if (value.isNotEmpty()) out += Segment.Text(value)
            prose.clear()
        }

        fun flushTable() {
            if (pipeBlock.isEmpty()) return
            val model = parsePipeTable(pipeBlock)
            pipeBlock.clear()
            if (model != null) {
                flushProse()
                out += Segment.Table(model)
            }
        }

        for (line in text.lineSequence()) {
            val trimmed = line.trimStart()
            val isPipeRow = trimmed.startsWith("|") && trimmed.count { it == '|' } >= 2
            if (isPipeRow) {
                flushProse()
                pipeBlock += line
            } else {
                flushTable()
                prose.appendLine(line)
            }
        }
        flushTable()
        flushProse()
        return out
    }

    private fun parsePipeTable(lines: List<String>): TableModel? {
        if (lines.size < 2) return null
        val cells = lines.map { line ->
            line.trim().trimStart('|').trimEnd('|').split('|').map { plainInline(it.trim()) }
        }
        val hasSeparator = cells.size >= 2 && cells[1].isNotEmpty() && cells[1].all { separatorCell.matches(it.trim()) }
        val header = if (hasSeparator) cells.first() else emptyList()
        val data = (if (hasSeparator) cells.drop(2) else cells).filter { row -> row.any { it.isNotBlank() } }
        val width = maxOf(header.size, data.maxOfOrNull { it.size } ?: 0)
        if (width < 2 || data.isEmpty()) return null

        fun pad(row: List<String>) = row + List((width - row.size).coerceAtLeast(0)) { "" }
        val paddedHeader = if (header.isEmpty()) emptyList() else pad(header)
        return TableModel(paddedHeader, data.map(::pad), inferKind(paddedHeader, width))
    }

    /**
     * A single reference page can repeat the same header many times (one table parses per
     * section of the form). Reading three identical headers in a row is noise, so adjacent
     * tables that share a header become one table.
     */
    private fun mergeAdjacentTables(segments: List<Segment>): List<Segment> {
        val merged = mutableListOf<Segment>()
        for (segment in segments) {
            val previous = merged.lastOrNull() as? Segment.Table
            if (segment is Segment.Table &&
                previous != null &&
                segment.model.kind != TableKind.NAV_CARDS &&
                previous.model.kind == segment.model.kind &&
                segment.model.header.isNotEmpty() &&
                previous.model.header == segment.model.header
            ) {
                merged[merged.lastIndex] = Segment.Table(
                    previous.model.copy(rows = previous.model.rows + segment.model.rows)
                )
            } else {
                merged += segment
            }
        }
        return merged
    }

    private fun stripTags(s: String): String = tagRegex.replace(s.replace("<br>", " ").replace("<br/>", " "), " ")

    private fun inferKind(header: List<String>, colCount: Int): TableKind {
        val h = header.map { it.lowercase() }
        val hasDescription = h.any { it.contains("description") || it.contains("details") }
        return when {
            h.isEmpty() && colCount >= 2 -> TableKind.GENERIC
            hasDescription && h.any { it.contains("type") } && colCount >= 3 -> TableKind.PARAMETERS
            hasDescription && colCount == 2 -> TableKind.PROPERTIES
            colCount >= 3 -> TableKind.PARAMETERS
            else -> TableKind.GENERIC
        }
    }

    /** Turns inline markdown in a cell into clean text (links keep their label). */
    private fun plainInline(raw: String): String =
        inlineLink.replace(raw, "$1")
            .replace(emphasis, "")
            .replace("""\(""", "(")
            .replace("""\)""", ")")
            .replace("""\[""", "[")
            .replace("""\]""", "]")
            .replace("\\_", "_")
            .replace(Regex("""\s+"""), " ")
            .trim()
}

sealed class Segment {
    data class Text(val content: String) : Segment()
    data class Table(val model: TableModel) : Segment()
}
